      type: 'choice',
      q: '1956 年召开的中共八大指出，国内的主要矛盾是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾。据此，八大提出党和人民的主要任务是',
      options: ['集中力量发展社会生产力，把我国从落后的农业国变为先进的工业国', '开展阶级斗争，防止资本主义复辟', '发动“大跃进”，尽快赶超英美', '对农业、手工业和资本主义工商业进行社会主义改造'],
