      ref: '（1）2021 年 7 月 1 日；到中国共产党成立一百年时全面建成小康社会。<br>（2）以中国式现代化全面推进中华民族伟大复兴（全面建成社会主义现代化强国、实现第二个百年奋斗目标）；人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路（任写两个）。<br>（3）成就：中国空间站全面建成（2022 年底）、北京冬奥会成功举办（2022 年）、天问一号成功着陆火星（2021 年）等；感想：国家综合国力和科技实力显著增强，作为青少年应努力学习，为 2035 年基本实现现代化贡献力量（言之有理即可）。',
