      html: `<p>材料一：</p><div class="source">经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地解决了绝对贫困问题，正在意气风发向着全面建成社会主义现代化强国的第二个百年奋斗目标迈进。<span class="from">——习近平在庆祝中国共产党成立 100 周年大会上的讲话（2021 年 7 月 1 日）</span></div>
<p>材料二（据中共二十大报告概述）：2022 年 10 月，中共二十大提出，从现在起中国共产党的中心任务就是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。中国式现代化是人口规模巨大的现代化，是全体人民共同富裕的现代化，是物质文明和精神文明相协调的现代化，是人与自然和谐共生的现代化，是走和平发展道路的现代化。</p>
<p>材料三（据史实概述）：2022 年 6 月 17 日，我国第三艘航空母舰在上海下水，命名为“福建舰”，舷号 18。它是我国完全自主设计建造的首艘弹射型航母。此前，我国已有“辽宁舰”（2012 年交付）和首艘国产航母“山东舰”（2019 年交付）。</p>`
