      title: '论述：我的 2035——从“三步走”到“两步走”',
      prompt: '<p>1987 年中共十三大提出“三步走”战略，2017 年中共十九大、2022 年中共二十大确立了“两步走”战略安排：到 2035 年基本实现社会主义现代化，到本世纪中叶建成社会主义现代化强国。到 2035 年，你二十多岁，正值青春年华。</p><p>请以“我与 2035”为题，写一段 150 字左右的短文：先说明从“三步走”到“两步走”现代化目标的变化，再结合中国式现代化的特色，谈谈你希望 2035 年的中国和福建是什么样子、你能为此做些什么。要求：史实准确，有真情实感。</p>',
      write: true,
      sample: '<p><b>史实</b>：1987 年中共十三大提出“三步走”，前两步在 20 世纪末完成，让中国人民解决了温饱、达到小康。2021 年我们全面建成小康社会，实现了第一个百年奋斗目标。2022 年中共二十大重申“两步走”：到 2035 年基本实现社会主义现代化，到本世纪中叶建成社会主义现代化强国，以中国式现代化全面推进中华民族伟大复兴。</p><p><b>我的 2035</b>：我希望那时的中国科技更强，空间站上有更多中国人的身影；我希望福建的武夷山依然青山绿水，闽江口的港口通向更多“一带一路”国家，这正是“人与自然和谐共生”“走和平发展道路”的中国式现代化。</p><p><b>我能做的</b>：现在学好本领，将来做一名工程师或教师，在自己的岗位上为基本实现现代化出一份力。</p>',
